        cc=section(tr('Proyecto académico de análisis comercial','Academic commercial analytics project',lang),'<p>'+tr('Este proyecto forma parte del caso conjunto de Business Intelligence. Allí se presentan las capturas, los archivos disponibles y las observaciones de calidad de cada implementación.','This project is part of the combined Business Intelligence case, with screenshots, available files and quality observations for each implementation.',lang)+'</p>'+button(tr('Explorar el caso de ','Explore the ',lang)+tool+' ↗','comercial.html#'+anchor,True))
        case_page(slug,tool+' · Sales Analysis',tr('Proyecto académico con datos de ventas de 2019.','Academic project using 2019 sales data.',lang),tr('Proyecto académico','Academic project',lang),[tool],cc,lang)

